282: #define TASK_SWITCH_SLEEP 10000
283: 
284: static void destroy_and_exit_process(process_rec *process,
285:                                      int process_exit_value)
286: {
287:     /*
288:      * Sleep for TASK_SWITCH_SLEEP micro seconds to cause a task switch on
289:      * OS layer and thus give possibly started piped loggers a chance to
290:      * process their input. Otherwise it is possible that they get killed
291:      * by us before they can do so. In this case maybe valuable log messages
292:      * might get lost.
293:      */
294: 
295:     /* If we are to print an error, we need the name before we destroy pool.
296:      * short_name is a pointer into argv, so remains valid.
297:      */
298:     const char *name = process->short_name ? process->short_name : "httpd";
299: 
300:     apr_sleep(TASK_SWITCH_SLEEP);
301:     ap_main_state = AP_SQ_MS_EXITING;
302:     apr_pool_destroy(process->pool); /* and destroy all descendent pools */
303:     apr_terminate();
304:     if ((process_exit_value != 0) && isatty(fileno(stderr))) {
305:         fprintf(stderr, "%s: abnormal exit %d\n", name, process_exit_value);
306:     }
307:     exit(process_exit_value);
308: }
