329: static void reset_process_pconf(process_rec *process)
330: {
331:     if (process->pconf) {
332:         apr_pool_clear(process->pconf);
333:         ap_server_conf = NULL;
334:     }
335:     else {
336:         apr_pool_create(&process->pconf, process->pool);
337:         apr_pool_tag(process->pconf, "pconf");
338:     }
339:     apr_pool_pre_cleanup_register(process->pconf, NULL, deregister_all_hooks);
340: }
