342: static process_rec *init_process(int *argc, const char * const * *argv)
343: {
344:     process_rec *process;
345:     apr_pool_t *cntx;
346:     apr_status_t stat;
347:     const char *failed = "apr_app_initialize()";
348: 
349:     stat = apr_app_initialize(argc, argv, NULL);
350:     if (stat == APR_SUCCESS) {
351:         failed = "apr_pool_create()";
352:         stat = apr_pool_create(&cntx, NULL);
353:     }
354: 
355:     if (stat != APR_SUCCESS) {
356:         /* For all intents and purposes, this is impossibly unlikely,
357:          * but APR doesn't exist yet, we can't use it for reporting
358:          * these earliest two failures;
359:          *
360:          * XXX: Note the apr_ctime() and apr_time_now() calls.  These
361:          * work, today, against an uninitialized APR, but in the future
362:          * (if they relied on global pools or mutexes, for example) then
363:          * the datestamp logic will need to be replaced.
364:          */
365:         char ctimebuff[APR_CTIME_LEN];
366:         apr_ctime(ctimebuff, apr_time_now());
367:         fprintf(stderr, "[%s] [crit] (%d) %s: %s failed "
368:                         "to initial context, exiting\n",
369:                         ctimebuff, stat, (*argv)[0], failed);
370:         apr_terminate();
371:         exit(1);
372:     }
373: 
374:     apr_pool_abort_set(abort_on_oom, cntx);
375:     apr_pool_tag(cntx, "process");
376:     ap_open_stderr_log(cntx);
377: 
378:     /* Now we have initialized apr and our logger, no more
379:      * exceptional error reporting required for the lifetime
380:      * of this server process.
381:      */
382: 
383:     process = apr_palloc(cntx, sizeof(process_rec));
384:     process->pool = cntx;
385: 
386:     process->pconf = NULL;
387:     reset_process_pconf(process);
388: 
389:     process->argc = *argc;
390:     process->argv = *argv;
391:     process->short_name = apr_filepath_name_get((*argv)[0]);
392: 
393: #if AP_HAS_THREAD_LOCAL
394:     {
395:         apr_status_t rv;
396:         apr_thread_t *thd = NULL;
397:         if ((rv = ap_thread_main_create(&thd, process->pool))) {
398:             char ctimebuff[APR_CTIME_LEN];
399:             apr_ctime(ctimebuff, apr_time_now());
400:             fprintf(stderr, "[%s] [crit] (%d) %s: failed "
401:                             "to initialize thread context, exiting\n",
402:                             ctimebuff, rv, (*argv)[0]);
403:             apr_terminate();
404:             exit(1);
405:         }
406:     }
407: #endif
408: 
409:     return process;
410: }
